(function () {
    cc.Xeng777HistoryItem = cc.Class({
        "extends": cc.Component,
        properties: {
            // sprite: cc.Sprite,
            lbSession: cc.Label,
            lbTime: cc.Label,
            lbBet: cc.Label,
            lbWin: cc.Label,
            lbNumResult: cc.Label,
            spriteDice1: cc.Sprite,
            spriteDice2: cc.Sprite,
            spriteDice3: cc.Sprite,
            spriteDiceBet: cc.Sprite,
        },

        updateItem: function (item, itemID) {
            // this.sprite.enabled = itemID % 2 !== 0;
            this.lbSession.string = '#' + item.SessionID;
            this.lbTime.string = cc.Tool.getInstance().convertUTCTime(item.CreateTime);
            let controller = cc.Xeng777Controller.getInstance();
            let isShowResultDices = item.Dice4 != 0;
            this.activeResultDices(isShowResultDices);
            if (isShowResultDices) {
                this.spriteDice3.spriteFrame = controller.getSpriteGateWin(parseInt(item.Dice3 - 1));
                this.lbNumResult.string = (item.Dice4 <= 9 ? '0' : '') + item.Dice4;

                if (item.Dice4 == 1) {
                    this.lbNumResult.spacingX = 0;
                } else if (item.Dice4 == 10) {
                    this.lbNumResult.spacingX = 10;
                } else if (item.Dice4 > 10) {
                    this.lbNumResult.spacingX = 0;
                }
                else {
                    this.lbNumResult.spacingX = -10;
                }
                this.spriteDice1.spriteFrame = controller.getSpriteGateBet(parseInt(item.Dice1 - 1));
                // this.spriteDice3.spriteFrame = controller.getSfDice(parseInt(item.Dice3) - 1);
            }

            this.spriteDiceBet.spriteFrame = controller.getSpriteGateBet(parseInt(item.GateID) - 1);

            this.lbBet.string = cc.Tool.getInstance().formatNumber(item.Bet / 1000.0);
            this.lbWin.string = cc.Tool.getInstance().formatNumber(item.Award / 1000.0);

            this.item = item;
            this.itemID = itemID;
        },
        activeResultDices: function (isActive) {
            this.spriteDice1.node.active = isActive;
            this.spriteDice2.node.active = isActive;
            this.spriteDice3.node.active = isActive;
        }
    });
}).call(this);